"""Browser progress for one upload, with a narrowly scoped series-selection grant."""
import json
from app.export.theme import browser_theme

STAGES={'receiving':'دریافت فایل ZIP','queued':'در صف پردازش','validating':'بررسی فایل‌های دایکام','awaiting_selection':'سری سی‌تی موردنظر را انتخاب کنید',
        'waiting_gpu':'در انتظار آزادشدن کارت گرافیک','running':'ناحیه‌بندی با کارت گرافیک در حال انجام است',
        'exporting':'ساخت فایل‌های نتیجه','resampling':'تطبیق ماسک با شبکهٔ اصلی تصویر','measurements':'محاسبهٔ اندازه‌گیری‌ها',
        'dicom_export':'ساخت خروجی DICOM','reusing_segmentation':'استفاده از ناحیه‌بندی معتبر قبلی',
        'creating_preview':'آماده‌سازی نمایشگر','creating_archive':'ساخت بستهٔ مستقل نتیجه','succeeded':'نتیجه آماده است','failed':'پردازش انجام نشد'}


def progress_page(id,token,can_select):
    payload=json.dumps({'id':id,'token':token,'canSelect':can_select,'stages':STAGES},ensure_ascii=False).replace('<','\\u003c')
    return '''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پیشرفت پردازش سی‌تی</title><style>__THEME_CSS__</style><style>body{background:var(--color-base-50);color:var(--color-base-800);font:16px Tahoma,Arial;line-height:1.9}main{max-width:760px;margin:70px auto;padding:28px;background:var(--color-base-25);border:1px solid var(--color-base-200);border-radius:16px}h1{font-size:26px}p{color:var(--color-base-600)}a{color:var(--color-primary-900)}button{background:var(--color-primary-800);color:var(--color-base-25);border:1px solid var(--color-primary-800);padding:12px 18px;border-radius:7px;font:inherit;cursor:pointer}button:disabled{opacity:.5}.series{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--color-base-200);padding:14px 0;gap:15px}.error{color:var(--color-warning-900)}progress{width:100%;accent-color:var(--color-primary)}code{direction:ltr;unicode-bidi:isolate;font-size:12px}</style></head><body><main><h1>نمایشگر و نتیجهٔ سی‌تی</h1><p>فایل روی همین سرور پردازش می‌شود. پس از آماده‌شدن نتیجه، نمایشگر به‌صورت خودکار باز خواهد شد.</p><progress id="busy" aria-label="پردازش در حال انجام است"></progress><h2 id="status">دریافت وضعیت…</h2><p id="error" class="error" role="status"></p><div id="series"></div><p id="selectionHelp"></p><p>شناسهٔ پردازش: <code id="job"></code></p><a href="/results" target="_blank" rel="noopener noreferrer">فهرست نتایج</a> · <a href="/docs">بازگشت به API</a></main><script>const upload=__PAYLOAD__;const statusNode=document.getElementById('status'),errorNode=document.getElementById('error'),list=document.getElementById('series');document.getElementById('job').textContent=upload.id;const base='/v1/uploads/'+upload.id;const query='?token='+encodeURIComponent(upload.token);let busy=false,selectionKey='',stopped=false;const fa=new Intl.NumberFormat('fa-IR');
async function poll(){if(busy||stopped)return;busy=true;try{const response=await fetch(base+'/browser-status'+query,{cache:'no-store'});if(!response.ok){if(response.status===403){stopped=true;document.getElementById('busy').hidden=true;throw Error('اعتبار لینک تمام شده است. لینک تازه را از پاسخ آپلود یا فهرست نتایج بگیرید.');}throw Error('دریافت وضعیت انجام نشد؛ اتصال به سرور را بررسی کنید.');}const state=await response.json();errorNode.textContent='';statusNode.textContent=upload.stages[state.stage]||upload.stages[state.status]||'در حال پردازش';document.getElementById('busy').hidden=['awaiting_selection','failed','succeeded'].includes(state.status);if(state.status==='succeeded'){if(state.viewer_url){location.replace(state.viewer_url);return;}stopped=true;throw Error('ناحیه‌بندی آماده است، ولی ساخت نمایشگر انجام نشد. فایل‌های نتیجه را از API دریافت کنید.');}if(state.status==='failed'){stopped=true;errorNode.textContent='کد خطا: '+(state.safe_error||'LOCAL_PROCESSING_FAILED');}if(state.status==='awaiting_selection'){const key=JSON.stringify(state.series);if(selectionKey!==key){selectionKey=key;list.replaceChildren();for(const series of state.series){if(series.modality!=='CT'||series.eligibility!=='eligible')continue;const row=document.createElement('div');row.className='series';const text=document.createElement('span');text.textContent='سری '+fa.format(series.index)+' · '+fa.format(series.slices)+' برش';row.append(text);if(upload.canSelect){const button=document.createElement('button');button.textContent='انتخاب و شروع ناحیه‌بندی';button.onclick=async()=>{for(const b of list.querySelectorAll('button'))b.disabled=true;try{const selected=await fetch(base+'/browser-select'+query,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({series_index:series.index})});if(!selected.ok)throw Error('انتخاب سری انجام نشد؛ وضعیت را دوباره بررسی کنید.');selectionKey='';list.replaceChildren();await poll();}catch(e){errorNode.textContent=String(e);for(const b of list.querySelectorAll('button'))b.disabled=false;}};row.append(button);}list.append(row);}document.getElementById('selectionHelp').textContent=upload.canSelect?'فقط سری انتخاب‌شده پردازش خواهد شد.':'این لینک فقط برای مشاهده است. برای انتخاب سری، لینک پاسخ اولیهٔ آپلود یا endpoint انتخاب سری در Swagger را باز کنید.';}}else{selectionKey='';list.replaceChildren();document.getElementById('selectionHelp').textContent='';}}catch(e){errorNode.textContent=e.message||String(e);}finally{busy=false;}}poll();setInterval(poll,2000);</script></body></html>'''.replace('__THEME_CSS__',browser_theme()).replace('__PAYLOAD__',payload)
